BEGIN;
CREATE TYPE sync_completeness AS ENUM ('COMPLETE','PARTIAL','FAILED');
CREATE TABLE series (ticker text PRIMARY KEY, venue text NOT NULL DEFAULT 'kalshi', title text NOT NULL, category text NOT NULL, frequency text NOT NULL, tags jsonb NOT NULL, contract_url text, contract_terms_url text, fee_type text, fee_multiplier numeric, additional_prohibitions jsonb NOT NULL, product_metadata jsonb NOT NULL, volume numeric, source_updated_at timestamptz, first_seen_at timestamptz NOT NULL, last_seen_at timestamptz NOT NULL, bot_ingested_at timestamptz NOT NULL, raw_spec_version text NOT NULL, metadata_hash text NOT NULL, raw_payload jsonb NOT NULL);
CREATE TABLE events (ticker text PRIMARY KEY, series_ticker text REFERENCES series(ticker), venue text NOT NULL DEFAULT 'kalshi', title text NOT NULL, category text, status text, source_updated_at timestamptz, first_seen_at timestamptz NOT NULL, last_seen_at timestamptz NOT NULL, bot_ingested_at timestamptz NOT NULL, raw_spec_version text NOT NULL, metadata_hash text NOT NULL, raw_payload jsonb NOT NULL);
CREATE TABLE markets (ticker text PRIMARY KEY, event_ticker text NOT NULL REFERENCES events(ticker), venue text NOT NULL DEFAULT 'kalshi', title text NOT NULL, market_type text NOT NULL, status text NOT NULL, expected_expiration_time timestamptz, expiration_time timestamptz, settlement_ts timestamptz, occurrence_datetime timestamptz, fractional_trading_enabled boolean NOT NULL, is_provisional boolean NOT NULL, is_multivariate boolean NOT NULL, price_level_structure text NOT NULL, price_ranges jsonb NOT NULL, volume numeric, open_interest numeric, source_updated_at timestamptz, first_seen_at timestamptz NOT NULL, last_seen_at timestamptz NOT NULL, bot_ingested_at timestamptz NOT NULL, raw_spec_version text NOT NULL, metadata_hash text NOT NULL, rules_hash text NOT NULL, raw_payload jsonb NOT NULL);
CREATE TABLE market_metadata_versions (market_ticker text REFERENCES markets(ticker), version integer NOT NULL, metadata_hash text NOT NULL, material jsonb NOT NULL, created_at timestamptz NOT NULL, PRIMARY KEY(market_ticker,version), UNIQUE(market_ticker,metadata_hash));
CREATE TABLE market_rules_versions (market_ticker text REFERENCES markets(ticker), version integer NOT NULL, rules_hash text NOT NULL, rules_primary text NOT NULL, rules_secondary text, material jsonb NOT NULL, created_at timestamptz NOT NULL, PRIMARY KEY(market_ticker,version), UNIQUE(market_ticker,rules_hash));
CREATE TABLE settlement_sources (id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY, venue text NOT NULL, name text NOT NULL, url text, canonical_hash text NOT NULL UNIQUE);
CREATE TABLE market_source_links (market_ticker text REFERENCES markets(ticker), settlement_source_id bigint REFERENCES settlement_sources(id), first_seen_at timestamptz NOT NULL, last_seen_at timestamptz NOT NULL, PRIMARY KEY(market_ticker,settlement_source_id));
CREATE TABLE series_source_links (series_ticker text REFERENCES series(ticker), settlement_source_id bigint REFERENCES settlement_sources(id), first_seen_at timestamptz NOT NULL, last_seen_at timestamptz NOT NULL, PRIMARY KEY(series_ticker,settlement_source_id));
CREATE TABLE market_sync_runs (run_id uuid PRIMARY KEY, endpoint text NOT NULL, mode text NOT NULL, started_at timestamptz NOT NULL, finished_at timestamptz, pages integer NOT NULL DEFAULT 0, records_received bigint NOT NULL DEFAULT 0, records_inserted bigint NOT NULL DEFAULT 0, records_updated bigint NOT NULL DEFAULT 0, records_unchanged bigint NOT NULL DEFAULT 0, malformed_records bigint NOT NULL DEFAULT 0, last_cursor text, completeness sync_completeness NOT NULL, failure text, previous_watermark timestamptz, requested_watermark timestamptz, confirmed_watermark timestamptz, source_latency_ms numeric);
CREATE TABLE market_sync_errors (id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY, run_id uuid REFERENCES market_sync_runs(run_id), endpoint text NOT NULL, cursor text, error_code text NOT NULL, detail text NOT NULL, happened_at timestamptz NOT NULL);
CREATE TABLE market_classifications (market_ticker text PRIMARY KEY REFERENCES markets(ticker), family text NOT NULL, kalshi_category text, series_ticker text, frequency text, is_multivariate boolean NOT NULL, is_provisional boolean NOT NULL, strategy_supported boolean NOT NULL DEFAULT false, quality_reasons jsonb NOT NULL, classified_at timestamptz NOT NULL, ruleset_version text NOT NULL);
CREATE TABLE market_orderbook_snapshots (id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY, market_ticker text NOT NULL REFERENCES markets(ticker), observed_at timestamptz NOT NULL, bot_ingested_at timestamptz NOT NULL, raw_yes_bids jsonb NOT NULL, raw_no_bids jsonb NOT NULL, normalized_yes_best_bid numeric, normalized_yes_best_ask numeric, spread numeric, raw_spec_version text NOT NULL);
CREATE TABLE historical_cutoff_state (singleton boolean PRIMARY KEY DEFAULT true CHECK(singleton), market_settled_ts timestamptz NOT NULL, trades_created_ts timestamptz NOT NULL, orders_updated_ts timestamptz NOT NULL, observed_at timestamptz NOT NULL);
CREATE INDEX markets_event_idx ON markets(event_ticker); CREATE INDEX markets_status_idx ON markets(status); CREATE INDEX markets_updated_idx ON markets(source_updated_at); CREATE INDEX book_market_time_idx ON market_orderbook_snapshots(market_ticker,observed_at DESC);
COMMIT;
